do $seed$
declare item jsonb; image jsonb; highlight jsonb; day jsonb; activity jsonb; package_uuid uuid; day_uuid uuid; position integer;
begin
 for item in select value from jsonb_array_elements('[{"id":"gorilla-queen-elizabeth","slug":"gorilla-trekking-and-queen-elizabeth-safari","title":"Gorilla Trekking Safari Experience","category":"Primate and wildlife safari","location":"Bwindi and Queen Elizabeth, Uganda","rating":4.9,"reviews":38,"durationDays":7,"priceFromUsd":3980,"shortDescription":"Track mountain gorillas, cruise the Kazinga Channel, and enjoy Uganda family safari comfort.","overview":"This carefully paced Uganda safari combines the life-changing experience of mountain gorilla trekking with the open savannahs, crater lakes, and boat safaris of Queen Elizabeth National Park. It is ideal for families and first-time visitors who want a premium route with expert local guidance, comfortable lodges, and time to absorb each destination.","mainImage":"/brand/gorilla-hero.jpg","heroImage":"/brand/gorilla-hero.jpg","galleryImages":["/brand/gorilla-hero.jpg","/brand/tree-lions.jpg","/brand/safari-vehicle.jpg","/brand/elephant.jpg"],"videoThumbnail":"/brand/tree-lions.jpg","type":"Adventure","groupSize":"2-12 People","language":"English","highlights":["Track mountain gorillas with expert local guides","Explore Uganda''s most iconic national parks","Enjoy comfortable safari lodges and scenic drives","Perfect for wildlife lovers and first-time visitors"],"included":["Pick and drop service","Professional safari guide","Comfortable accommodation","Park entry support","Selected meals"],"excluded":["International flights","Visa fees","Personal expenses","Tips and gratuities","Optional activities"],"itineraryDays":[{"dayNumber":1,"title":"Arrival in Entebbe","overview":"Land in Entebbe and settle into a calm lakeside stay before your safari begins.","accommodationName":"Boutique guesthouse","activities":[{"title":"Arrival assistance","description":"Meet your driver-guide and review the days ahead."}],"images":["/brand/safari-vehicle.jpg","/brand/gorilla-hero.jpg","/brand/tree-lions.jpg"]},{"dayNumber":2,"title":"