.jpg","/brand/gorilla-hero.jpg"]},{"dayNumber":2,"title":"Scenic Transfer and Lodge Check-In","overview":"Experience a carefully paced day around Lake Bunyonyi, Uganda, with guided activities, scenic stops, and time to settle into the rhythm of your safari.","accommodationName":"Safari lodge","activities":[{"title":"Guided experience","description":"Your guide shapes the day around wildlife, scenery, comfort, and local insight."}],"images":["/brand/elephant.jpg","/brand/safari-vehicle.jpg","/brand/tree-lions.jpg"]},{"dayNumber":3,"title":"Guided Wildlife Drive","overview":"Experience a carefully paced day around Lake Bunyonyi, Uganda, with guided activities, scenic stops, and time to settle into the rhythm of your safari.","accommodationName":"Safari lodge","activities":[{"title":"Guided experience","description":"Your guide shapes the day around wildlife, scenery, comfort, and local insight."}],"images":["/brand/safari-vehicle.jpg","/brand/safari-vehicle.jpg","/brand/safari-vehicle.jpg"]},{"dayNumber":4,"title":"Boat Safari and Local Landscapes","overview":"Experience a carefully paced day around Lake Bunyonyi, Uganda, with guided activities, scenic stops, and time to settle into the rhythm of your safari.","accommodationName":"Safari lodge","activities":[{"title":"Guided experience","description":"Your guide shapes the day around wildlife, scenery, comfort, and local insight."}],"images":["/brand/gorilla-hero.jpg","/brand/safari-vehicle.jpg","/brand/elephant.jpg"]},{"dayNumber":5,"title":"Departure Transfer","overview":"Enjoy a flexible final morning before your transfer and onward travel from Lake Bunyonyi, Uganda.","accommodationName":"Departure day","activities":[{"title":"Departure support","description":"Your guide assists with timing, luggage, and onward connections."}],"images":["/brand/elephant.jpg","/brand/safari-vehicle.jpg","/brand/safari-vehicle.jpg"]}],"mapLocation":"Lake Bunyonyi, Uganda"}]'::jsonb) loop
  package_uuid := null;
  insert into public.tour_packages(title,slug,category,duration_days,price_from_usd,price_mid_range_usd,short_description,overview,main_image_url,hero_image_url,status,display_order)
  values(item->>'title',item->>'slug',item->>'category',(item->>'durationDays')::integer,(item->>'priceFromUsd')::numeric,(item->>'priceFromUsd')::numeric,item->>'shortDescription',item->>'overview',item->>'mainImage',item->>'heroImage','published',1+(select count(*) from public.tour_packages))
  on conflict(slug) do nothing returning id into package_uuid;
  if package_uuid is null then continue; end if;
  position := 0;
  for image in select value from jsonb_array_elements(item->'galleryImages') loop
   insert into public.tour_gallery_images(package_id,image_url,sort_order) values(package_uuid,image#>>'{}',position);
   position := position + 1;
  end loop;
  position := 0;
  for highlight in select value from jsonb_array_elements(item->'highlights') loop
   insert into public.tour_highlights(package_id,title,sort_order) values(package_uuid,highlight#>>'{}',position);
   position := position + 1;
  end loop;
  for day in select value from jsonb_array_elements(item->'itineraryDays') loop
   insert into public.tour_itinerary_days(package_id,day_number,title,overview,accommodation_name,sort_order)
   values(package_uuid,(day->>'dayNumber')::integer,day->>'title',day->>'overview',day->>'accommodationName',(day->>'dayNumber')::integer)
   returning id into day_uuid;
   position := 0;
   for image in select value from jsonb_array_elements(day->'images') loop
    insert into public.tour_itinerary_images(itinerary_day_id,image_url,sort_order) values(day_uuid,image#>>'{}',position);
    position := position + 1;
   end loop;
   position := 0;
   for activity in select value from jsonb_array_elements(day->'activities') loop
    insert into public.tour_itinerary_activities(itinerary_day_id,title,description,sort_order) values(day_uuid,activity->>'title',activity->>'description',position);
    position := position + 1;
   end loop;
  end loop;
 end loop;
end $seed$;
commit;
